Method.Implementation:
   Set tSC= $$$OK
   $$$TRACE(" Inside InvokePostService ")

   try {
	 set httpBodyData = pInput.Read(.len,.status)
	 $$$TRACE(" httpBody : "_httpBodyData)	 
	 set rec = ##class(%DynamicObject).%FromJSON(pInput)

	 set lastName = rec.patient.lastName
     $$$TRACE("Last Name: "_lastName)
	 set firstName = rec.patient.firstName
	 set middleName = rec.patient.middleName
	 set mrn = rec.patient.mrn
	 set sex = rec.patient.gender
	 set dob = rec.patient.dateOfBirth
	 set fin = rec.visit.visitNumber
	 set vtype = rec.visit.visitType
	 set facId = rec.visit.facilityCode

	 if mrn="" {
		 $$$TRACE("Bad data, MRN is null... ")
		 set errTxt = "Post request failed to process. Error: MRN is null."
		 //Construct error response
         set responseMsg="{"_$CHAR(34)_"status"_$CHAR(34)_":{"_$CHAR(34)_"error"_$CHAR(34)_":"_errTxt_","_$CHAR(34)_"summary"_$CHAR(34)_":"_$CHAR(34)_$CHAR(34)_"}}"
         Set pOutput=##class(%GlobalBinaryStream).%New()
         Do pOutput.SetAttribute("Content-Type","application/json")
         do pOutput.Write(responseMsg)
		 //Set %response.Status=$G(resp("ResponseCode"),"400 Bad Request")
		 //Set tSC = ##class(IHC.ITF.ITFCOMMON.Utility).InputDataError(..%ConfigName,errTxt_" Raw Data: "_httpBodyData)	 
		 Do:$$$ISOK(tSC) pOutput.SetAttribute("ResponseCode","400 Bad Request")

	 }
	 else {
	    // Construct a HL7 message
	    set pHL7 = ##class(EnsLib.HL7.Message).%New()
	    set pHL7.DocType = "R1PreRegAdt:R1ADT"
	    set ctrlId=$zstrip($ZDATETIME($ZTIMESTAMP,3,1,4), "*P")
	    set msgTm=##class(Ens.Util.FunctionSet).SubString(ctrlId,1,14)
	    set tSeg1 = ##class(EnsLib.HL7.Segment).ImportFromString("MSH|^~\&|MH|"_facId_"|||"_msgTm_"||ADT^A08|"_ctrlId_"|T|2.3.1|")
	    set tSeg2 = ##class(EnsLib.HL7.Segment).ImportFromString("EVN|A08|"_msgTm_"||1|")
	    set tSeg3 = ##class(EnsLib.HL7.Segment).ImportFromString("PID|1||"_mrn_"||"_lastName_"^"_firstName_"^"_middleName_"||"_dob_"|"_sex_"||||||||||"_fin_"||||||||||||N|")
	    set tSeg4 = ##class(EnsLib.HL7.Segment).ImportFromString("PV1|1||"_facId_"||||||||||||||||"_fin_"|")
	    set tsc = pHL7.SetSegmentAt(tSeg1,1)
	    set tsc = pHL7.InsertSegmentAt(tSeg2,2)	
	    set tsc = pHL7.InsertSegmentAt(tSeg3,3)
	    set tsc = pHL7.InsertSegmentAt(tSeg4,4)
        set obxSegIndx=1
        set segCnt=4
        #dim docIter As %Iterator.Array
        if $isObject(rec) {
           $$$TRACE("Loop Documents...")
           set iterator =  rec.%GetIterator()
           while iterator.%GetNext(.key,.value) { 
	          $$$TRACE(" Key1: "_key_" Value: "_value)
              if (key="documents") {
	             set docIter=value.%GetIterator()
	             if (##class(Ens.Util.FunctionSet).Contains(value,"DynamicArray")) {
	                while docIter.%GetNext(.key,.value) { 
                       if $isObject(value) {
	                      set obxs=..createObxSegments(value,obxSegIndx)
		         	      set recCnt=obxs.Size
                          if recCnt > 0 {
                             for i=1:1:recCnt {
		 	                    set obxstr=obxs.GetAt(i)
		        	            set tObxSeg=##class(EnsLib.HL7.Segment).ImportFromString(obxstr)
		        	            set segCnt=segCnt+1
		        	            set obxSegIndx=obxSegIndx+1
                	            set tsc = pHL7.InsertSegmentAt(tObxSeg,segCnt)
                             }
                          }
                       }
                    }
	              }
	              else {
		             set obxs=..createObxSegments(value,1)
		         	 set recCnt=obxs.Size
                     if recCnt > 0 {
                        for i=1:1:recCnt {
		 	               set obxstr=obxs.GetAt(i)
		        	       set tObxSeg=##class(EnsLib.HL7.Segment).ImportFromString(obxstr)
		        	       set segCnt=segCnt+1
                	       set tsc = pHL7.InsertSegmentAt(tObxSeg,segCnt)
                        }
                     }
	              }
               }
            }
         }
	  do ..SendRequestAsync(..TargetConfigNames,pHL7)	
	  $$$TRACE("***Sent the HL7 Message ****")

      //Construct response data
      set responseMsg="{"_$CHAR(34)_"MessageId"_$CHAR(34)_":"_ctrlId_"}"
	  Set pOutput=##class(%GlobalBinaryStream).%New()
      do pOutput.Write(responseMsg)
      Do:$$$ISOK(tSC) pOutput.SetAttribute("ResponseCode","200 record is processed ok.")
   }

 }catch e
	{
		 $$$TRACE(" Unknown Exception: " _ e)
		 set errTxt = "Post request failed to process. Error:"_e.Name_" at: "_e.Location
		 $$$TRACE("Execption  Error: " _ errTxt)
		 //Construct error response
         set responseMsg="{"_$CHAR(34)_"status"_$CHAR(34)_":{"_$CHAR(34)_"error"_$CHAR(34)_":"_errTxt_","_$CHAR(34)_"summary"_$CHAR(34)_":"_$CHAR(34)_$CHAR(34)_"}}"
         Set pOutput=##class(%GlobalBinaryStream).%New()
         Do pOutput.SetAttribute("Content-Type","application/json")
         do pOutput.Write(responseMsg)
		 //Set %response.Status=$G(resp("ResponseCode"),"415 content type is not application/json")
		 //Set tSC = ##class(IHC.ITF.ITFCOMMON.Utility).InputDataError(..%ConfigName,errTxt_" Raw Data: "_httpBodyData)	 
		 Do:$$$ISOK(tSC) pOutput.SetAttribute("ResponseCode","415 content type is not application/json")
	}
    Quit tSC

	set tmp="temp"
	set obxStr=""
	set docId=""
	set docName=""
	set cerDocType=""
	set docRefId=""
	set docSignedDate=""
	set mspQlf=""
	set sobxIndx=1
	Set obxArray = ##class(%ListOfDataTypes).%New()
	do obxArray.Insert("temp")
	set iter = doc.%GetIterator()
    while iter.%GetNext(.key,.value) { 
                 	if (key="aliasDocumentId"){
                       set docId=value
	                }
	                elseif (key="documentName") {
		                set docName=value
	                }
	                elseif (key="cernerDocumentType") {
		                set cerDocType=value
	                }
	                elseif (key="cernerDocumentReferenceId") {
		                set docRefId=value
	                }

	                elseif (key="documentSignedDate") {
		                set docSignedDate=value
	                }
	                elseif (key="data") {
		                set msps=value
		                $$$TRACE("Loop MSPGs...")
                        set iterator1 =  msps.%GetIterator()
                        while iterator1.%GetNext(.key1,.value1) { 
                           $$$TRACE(" Key1: "_key1_" Value1: "_value1)
                           if (key1="qualifier") {
	                           set mspQlf=value1
                           }
                           elseif (key1="values") {
                               if $isObject(value1) {
       			                  set iterator2 =  value1.%GetIterator()
       			                  while iterator2.%GetNext(.key2,.value2) { 
          			                  $$$TRACE(" Key2: "_key2_" Value2: "_value2)
          			                  set tObxSeg=..createObxSegmentStr(mspQlf,key2,value2,obxInx,sobxIndx,docSignedDate)
          			                  $$$TRACE(" OBX string: "_tObxSeg)
          			                  set sobxIndx=sobxIndx+1
          			                  do obxArray.Insert(tObxSeg)
                 	              }
               	               }
	         	           }
                        }
	                }
    } 
    $$$TRACE("Create OBX segment #"_obxInx)
    set obxStr = "OBX|"_obxInx_"|ST|"_docId_"^"_docName_"^"_cerDocType_"||"_docRefId_"||||||F|||"_docSignedDate_"|"
    do obxArray.SetAt(obxStr,1)
	Quit obxArray

Do ##super(.pArray,pItem)
If pItem.GetModifiedSetting("TargetConfigNames",.tValue) {
	For i=1:1:$L(tValue,",") { Set tOne=$ZStrip($P(tValue,",",i),"<>W")  Continue:""=tOne  Set pArray(tOne)="" }
}
